head.script:
// 테스트 설명, 유효성 값 설정
//  _1 : 기본 구성
//   - Body 가 MultiLine 일때의 rowIndex / colIndex 하위절은 _2 샘플에서 다루므로 제외
//   - DrillDown 으로 숨겨진 Row 관련 하위절은 _3 샘플에서 다루므로 제외
//   - onbeforeedit 는 @return 이 비어있어 반환값으로 편집 진입을 취소할 수 없으므로 반환값 관련 검증 없음
scwin.tData = {
    "description" : "[gridView > E > onbeforeedit]<br/>Body Cell 이 편집 상태로 변경되기 직전에 발생합니다.",
    "validation" : [
        "rowIndex 파라미터는 편집중인 Body Cell 의 Row 인덱스값을 갖습니다.",
        "rowIndex 파라미터는 GridView 에 표시된 Row 를 기준으로 인덱스가 설정됩니다.",
        "colIndex 파라미터는 편집중인 Body Cell 의 Column 인덱스값을 갖습니다.",
        "colIndex 파라미터는 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "value 파라미터는 편집 상태로 변경되기 직전의 Body Cell 데이터를 문자열로 갖습니다.",
        "편집 상태 변경과 관련된 이벤트는 onbeforeedit -> oneditend -> onafteredit -> onviewchange 순서로 발생합니다.",
        "viewChangeAfterEdit=true 인 경우엔 이벤트가 onbeforeedit -> oneditend -> onviewchange -> onafteredit 순서로 변경됩니다."
    ]
}



//  seq : 한 번의 편집 조작(편집 시작 -> 편집 종료) 안에서 이벤트 발생 순번
scwin.gVar = { "seq" : 0 };



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값을 명시 설정한다.
    //  con_viewChangeAfterEdit 는 gdl_boolean 바인딩 -> 코드값 : 미설정="1" / true="2" / false="3"
    con_viewChangeAfterEdit.setValue("1");

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  editable="true" 로 편집 가능한 GridView 를 구성한다.
//  Body Column 4개 (인덱스 0~3)
//   - 인덱스 0 : 이름
//   - 인덱스 1 : 메모 -> setColumnVisible(1, false) 로 숨김. 숨겨진 Column 도 인덱스에 포함되는지 검증용
//   - 인덱스 2 : 부서 (화면상으로는 두번째 Column 이지만 인덱스는 2)
//   - 인덱스 3 : 금액
//  DataList 는 6건이지만 use 값이 Y 인 4건만 필터로 표시하여
//  표시 Row 인덱스(0~3) 와 DataList Row 인덱스(0, 2, 4, 5) 가 서로 다르도록 구성한다.
//  con_viewChangeAfterEdit : viewChangeAfterEdit 속성값 (미설정/true/false) - 렌더 시 결정되므로 Target 재생성으로 반영
scwin.comp_init = async function () {
    // 편집 상태에서 재생성하면 편집 종료 처리가 이미 제거된 대상을 참조하므로,
    //  재생성 전에 편집 상태를 먼저 빠져나오고 예약된 편집 종료 처리가 끝날 때까지 기다린다.
    try {
        if (document.activeElement && typeof document.activeElement.blur === "function") {
            document.activeElement.blur();
        }
    } catch (e) { }
    await new Promise(function (resolve) { setTimeout(resolve, 50); });

    // 기존 target / dataList 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    scwin.gVar.seq = 0;

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // viewChangeAfterEdit 옵션 (gdl_boolean 이므로 getText 로 ''/true/false 라벨을 읽는다)
    //  미설정('') 이면 createCList 가 빈값을 제외하여 속성 자체를 부여하지 않는다.
    let viewChangeAfterEdit = con_viewChangeAfterEdit.getText();
    let strVCAELabel = (viewChangeAfterEdit === "") ? "미설정" : viewChangeAfterEdit;

    // 조작 절차 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 편집 가능(editable=true) 그리드이며 Body Column 인덱스는 0=이름, 1=메모(숨김 Column), 2=부서, 3=금액 입니다. 숨겨진 메모 Column 때문에 화면상 두번째 Column 인 부서의 인덱스는 2 입니다.\n[전제] DataList 6건 중 2건이 필터로 제외되어 표시 Row 인덱스(0, 1, 2, 3) 와 DataList Row 인덱스(0, 2, 4, 5) 가 서로 다릅니다.\n[전제] viewChangeAfterEdit 의 기본값은 미설정이며 현재 ' + strVCAELabel + ' 입니다. 값을 바꾼 뒤에는 Target 재생성 버튼을 눌러야 반영됩니다.\n[절차1] Body Cell 을 더블클릭해 편집 상태로 만들면 onbeforeedit 이 발생합니다. 출력된 rowIndex, colIndex, value 를 편집한 Cell 의 위치 및 편집 전 표시값과 대조합니다.\n[절차2] 편집 상태에서 값을 다른 값으로 바꾼 뒤 다른 Cell 을 클릭하거나 Tab 키로 포커스를 옮겨 편집을 종료합니다.\n[절차3] 같은 Cell 을 다시 더블클릭해 onbeforeedit 의 value 가 절차2 에서 저장된 값으로 갱신되는지 확인합니다. 편집 중 입력한 값이 아니라 편집 진입 직전의 값이 전달됩니다.\n[절차4] 숨김 Column 의 영향은 화면상 두번째 Column 인 부서 Cell 을, 표시 Row 기준은 마지막 Row 를 편집하여 확인합니다.\n[절차5] viewChangeAfterEdit 을 미설정, true, false 로 각각 바꿔 Target 재생성 버튼을 누른 뒤 절차1 과 절차2 를 다시 수행합니다. 값을 실제로 변경해야 onviewchange 까지 발생합니다.\n[확인] 결과창 각 줄 앞의 순번으로 이벤트 발생 순서를 확인합니다. 순번은 편집 조작마다 1 부터 다시 시작합니다."', '', 'label1');

    // dataList 생성 (5 Column, 6 Row)
    //  - name / memo / dept / amt 는 Body Column 인덱스 0~3 과 순서가 일치
    //  - use 는 표시 대상 여부(Y/N) 로 필터에만 사용하며 화면에는 표시하지 않음
    let strData = '';
    strData += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strData += '<w2:columnInfo>';
    strData += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strData += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strData += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strData += '<w2:column id="amt" name="amt" dataType="text"></w2:column>';
    strData += '<w2:column id="use" name="use" dataType="text"></w2:column>';
    strData += '</w2:columnInfo>';
    strData += '<w2:data use="true"></w2:data>';
    strData += '</w2:dataList>';
    $p.data.create(strData);

    let jsonData = [
        { "name" : "이름1", "memo" : "메모1", "dept" : "개발", "amt" : "10", "use" : "Y" },
        { "name" : "이름2", "memo" : "메모2", "dept" : "개발", "amt" : "20", "use" : "N" },
        { "name" : "이름3", "memo" : "메모3", "dept" : "영업", "amt" : "30", "use" : "Y" },
        { "name" : "이름4", "memo" : "메모4", "dept" : "영업", "amt" : "40", "use" : "N" },
        { "name" : "이름5", "memo" : "메모5", "dept" : "기획", "amt" : "50", "use" : "Y" },
        { "name" : "이름6", "memo" : "메모6", "dept" : "기획", "amt" : "60", "use" : "Y" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // use 값이 Y 인 Row 만 표시 -> 표시 Row 인덱스와 DataList Row 인덱스가 달라진다.
    dlt_bind.setFilter({ type : "row", colIndex : "use", key : "Y", condition : "and", exactMatch : true, clearFilter : "all" });

    let properties = {
        dataList : "data:dlt_bind",
        editable : "true",
        viewChangeAfterEdit : viewChangeAfterEdit
    };
    let cList = $c.gcm.createCList(properties);

    // 편집 상태 변경과 관련된 4개 이벤트를 모두 등록하여 발생 순서를 확인한다.
    //  (oneditend / onafteredit / onviewchange 는 순서 확인용이며 검증 대상은 onbeforeedit 이다)
    let eList = $c.gcm.createEList(["onbeforeedit", "oneditend", "onafteredit", "onviewchange"]);

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" style="width:640px;height:220px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol1" value="0 : 이름"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="1 : 메모 (숨김)"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol3" value="2 : 부서"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="3 : 금액"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="memo" dataList="memo"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="amt" dataList="amt"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // 두번째 Column(인덱스 1) 숨김 -> 숨겨진 Column 도 인덱스에 포함되는지 검증용
    scwin.target1.setColumnVisible(1, false);
}



// con_viewChangeAfterEdit 변경은 Target 재생성 버튼으로만 반영한다.



// 이벤트 발생 순서 출력 공통 함수
//  - 각 핸들러가 발생 즉시 한 줄씩 출력하므로 출력 순서 = 실제 발생 순서
//  - 순번은 하나의 편집 조작(편집 시작 -> 편집 종료) 마다 1 부터 다시 시작한다.
scwin.logEvent = function (message) {
    scwin.gVar.seq++;
    wf_body_bottom.getObj("scwin").setReturnValue("[" + scwin.gVar.seq + "] " + message);
}



// onbeforeedit : Body Cell 이 편집 상태로 변경되기 직전에 발생 (검증 대상)
//  - 표준 DOM 이벤트 객체가 아닌 개별 파라미터(rowIndex, colIndex, value) 이므로 각각 출력한다.
//  - rowIndex 는 표시 Row 기준이므로 getRealRowIndex 로 구한 DataList Row 인덱스와 함께 출력해 대비한다.
//  - 편집 조작 단위로 순번을 매기기 위해 발생 시점에 순번을 초기화한다.
scwin.target1_onbeforeedit = function (rowIndex, colIndex, value) {
    let bottom = wf_body_bottom.getObj("scwin");

    scwin.gVar.seq = 0;
    scwin.logEvent("onbeforeedit 발생");
    bottom.setReturnValue("rowIndex : " + rowIndex + " (DataList Row 인덱스 : " + target1.getRealRowIndex(rowIndex) + ")");
    bottom.setReturnValue("colIndex : " + colIndex);
    bottom.setReturnValue("편집 진입 직전의 value : " + value + " (타입 : " + (typeof value) + ")");
}



// 발생 순서 확인용 (검증 대상 아님)
scwin.target1_oneditend = function (rowIndex, colIndex, value) {
    scwin.logEvent("oneditend 발생");
}

// onafteredit 의 value 는 편집으로 반영된 값이므로 onbeforeedit 의 진입 직전 값과 대비하여 출력한다.
scwin.target1_onafteredit = function (rowIndex, colIndex, value) {
    scwin.logEvent("onafteredit 발생");
    wf_body_bottom.getObj("scwin").setReturnValue("편집 완료 후의 value : " + value);
}

scwin.target1_onviewchange = function (info) {
    scwin.logEvent("onviewchange 발생");
}
